				if (msg.entry) appendTurn(msg.entry);
			} else if (msg.type === "thinking") {
				statusEl.textContent =
					msg.route === "operator"
						? "Operator is listening..."
						: `${whoEl.textContent || "working"} is working...`;
				startActivity(
					msg.route === "operator"
						? "Operator"
						: whoEl.textContent || "working",
				);
