				} else {
					statusEl.textContent =
						"Got it — you're next, once this turn finishes.";
				}
				statusEl.classList.remove("error");
			} else if (msg.type === "reply") {
				stopActivity();
				statusEl.textContent = idleText;
				appendTurn({
					role: "agent",
