                .trim()
                .chars()
                .take(300)
                .collect::<String>();
            return Err(AudioError::Process(format!(
                "STT sidecar exited unsuccessfully{}",
                if detail.is_empty() {
                    String::new()
                } else {
                    format!(": {detail}")
                }
            )));
        }
